import{_ as t,o,c as a,a3 as n}from"./chunks/framework.BTQ4eCVb.js";const u=JSON.parse('{"title":"Payments Module","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Payments Module | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/payments-overview"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Payments Module | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/payments-overview"}]]},"headers":[],"relativePath":"user-guide/payments-overview.md","filePath":"user-guide/payments-overview.md","lastUpdated":1787861406000}'),i={name:"user-guide/payments-overview.md"};function s(d,e,r,c,l,m){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="payments-module" tabindex="-1">Payments Module <a class="header-anchor" href="#payments-module" aria-label="Permalink to &quot;Payments Module&quot;">​</a></h1><p>Tenant customer-billing module on the frozen platform — the second Phase 3 (Billing) module, shipped alongside <a href="/user-guide/invoices-overview">Invoices</a>. Records payments a tenant receives from its own customers and allocates them against outstanding <a href="/user-guide/invoices-overview">Invoices</a>, driving the invoice&#39;s <code>amount_paid</code> / <code>balance_due</code> / status forward.</p><p><strong>Hard dependency on Invoices.</strong> Unlike Invoices (which installs standalone), Payments declares a <strong>required</strong> <code>module_dependencies</code> row on Invoices — a workspace must have Invoices installed before Payments can be enabled from Marketplace.</p><blockquote><p><strong>Naming note:</strong> the backend model is <code>CustomerPayment</code> (table <code>customer_payments</code>) — distinct from the platform&#39;s own <strong>Central Billing → Payments</strong> ledger (subscription payments the platform charges <em>tenants</em> for their module licenses). This module records payments a tenant receives <em>from its own customers</em>.</p></blockquote><h2 id="guides" tabindex="-1">Guides <a class="header-anchor" href="#guides" aria-label="Permalink to &quot;Guides&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Audience</th><th>Document</th></tr></thead><tbody><tr><td>Operators / workspace users</td><td><a href="/user-guide/payments">payments.md</a></td></tr><tr><td>Engineers</td><td><a href="/developer-guide/payments">payments.md</a></td></tr><tr><td>Production / ops</td><td><a href="/deployment/payments">payments.md</a></td></tr><tr><td>Module Development Standard</td><td><a href="/developer-guide/module-development">module-development.md</a></td></tr><tr><td>Reference blueprint</td><td><a href="/user-guide/invoices-overview">invoices-overview.md</a></td></tr><tr><td>Tenant API</td><td><a href="/api/tenant-v1-payments">../api/tenant-v1-payments.md</a></td></tr></tbody></table><h2 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h2><ul><li>Payment fields: amount, currency, method (<code>cash</code>, <code>bank_transfer</code>, <code>cheque</code>, <code>card_manual</code>, <code>other</code>), paid-at date, reference, notes, optional contact/company link, optional <code>deposit_account_id</code> (Accounting soft dep)</li><li>Auto-numbered (<code>PAY-00001</code>; prefix backed by the <code>payments_number_prefix</code> tenant setting, default <code>PAY-</code> — editable under <strong>Settings → General → Document number prefixes</strong>)</li><li>Allocations — split a payment&#39;s amount across one or more invoices (<code>customer_invoice_id</code> + <code>amount</code> per row); stored on draft but only applied to invoice balances once <strong>posted</strong></li><li>Status workflow: <code>draft → posted → void</code> (<code>POST /payments/{id}/post</code>, <code>.../void</code>) — posting a payment adds each allocation to its invoice&#39;s <code>amount_paid</code> and recalculates the invoice balance/status; when Accounting is installed, also posts Dr deposit / Cr AR; voiding reverses allocations and voids the linked journal</li><li>Assignment with assignee scoping via <code>payments.assign</code></li><li>Notes + domain activity timeline (mirrors Invoices)</li><li><strong>Posted</strong> payments: branded <strong>receipt PDF</strong> (<code>GET /payments/{id}/pdf</code>) and <strong>email receipt</strong> (<code>POST /payments/{id}/email</code>, <code>payments.send</code>) — mirrors invoice/estimate/quotation email; only <code>posted</code> status (draft/void → 422)</li><li>Trash filtering plus <strong>Restore</strong> and <strong>Delete permanently</strong></li><li>Module licensing (<code>module:payments</code>) + Spatie permissions — <strong>free Marketplace opt-in</strong> (Billing category), <strong>requires Invoices</strong>; optional soft dep on Accounting</li><li>Audit + activity logging; assignment notification</li></ul><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p><code>payments.view</code> · <code>create</code> · <code>update</code> · <code>delete</code> · <code>restore</code> · <code>force.delete</code> · <code>assign</code> · <code>post</code> · <code>void</code> · <code>send</code></p><p>Enable Payments from Marketplace (free) — <strong>Invoices must already be installed</strong>; Marketplace blocks the install otherwise. Catalog: slug <code>payments</code>, category <code>billing</code>, <code>is_default_included = false</code>, <code>is_billable = false</code>, <code>sort_order = 20</code>. Version <strong>1.2.0</strong>.</p><h2 id="related-modules" tabindex="-1">Related modules <a class="header-anchor" href="#related-modules" aria-label="Permalink to &quot;Related modules&quot;">​</a></h2><p><strong>Required:</strong> <a href="/user-guide/invoices-overview">Invoices</a> — Payments cannot be installed or record allocations without it. <strong>Optional:</strong> Contacts and Companies (customer pickers only appear/validate when entitled); <a href="/user-guide/accounting-overview">Accounting</a> for deposit accounts + auto-journals. See <a href="/architecture/module-dependencies">Module Dependencies</a>.</p><h2 id="explicitly-deferred" tabindex="-1">Explicitly deferred <a class="header-anchor" href="#explicitly-deferred" aria-label="Permalink to &quot;Explicitly deferred&quot;">​</a></h2><ul><li>Partial refunds of a posted payment (today, voiding reverses the full allocation set)</li><li>Payment gateway capture (online card/bank payments) — this module only records payments received through other channels</li><li>Multi-currency conversion</li></ul>',15)])])}const g=t(i,[["render",s]]);export{u as __pageData,g as default};
